#!/usr/bin/env bash
# Question 1: Ready, but one worker misbehaves. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

[[ "$CKA_NODE" == "${Q1_NODE}" ]] || exit 0

case "${Q1_FAULT}" in
  kubelet-port-blocked)
    printf '%s\n' '#!/bin/bash' 'while true; do' '  iptables -t filter -C INPUT -p tcp --dport 10250 -j REJECT --reject-with tcp-reset 2>/dev/null || iptables -t filter -I INPUT 1 -p tcp --dport 10250 -j REJECT --reject-with tcp-reset 2>/dev/null' '  sleep 3' 'done' > /usr/local/sbin/node-hardening
    chmod 755 /usr/local/sbin/node-hardening
    printf '%s\n' '[Unit]' 'Description=Node hardening rules' 'After=network.target' '[Service]' 'ExecStart=/usr/local/sbin/node-hardening' 'Restart=always' '[Install]' 'WantedBy=multi-user.target' > /etc/systemd/system/node-hardening.service
    systemctl daemon-reload
    systemctl enable --now node-hardening >/dev/null 2>&1
    sleep 1
    systemctl is-active --quiet node-hardening || { echo "the hardening service did not start" >&2; exit 1; }
    ;;
  cluster-dns-wrong)
    cp -a /var/lib/kubelet/config.yaml "/var/tmp/cka-q1.kubelet-config"
    sed -i -E '/^clusterDNS:/{n;s/^- .*/- 10.96.0.53/}' /var/lib/kubelet/config.yaml
    grep -A1 '^clusterDNS:' /var/lib/kubelet/config.yaml | grep -q '10.96.0.53' || { echo "could not edit /var/lib/kubelet/config.yaml" >&2; exit 1; }
    systemctl restart kubelet || true
    ;;
  sandbox-image-wrong)
    cp -a /etc/containerd/config.toml "/var/tmp/cka-q1.containerd"
    sed -i -E "s#^([[:space:]]*sandbox = ).*#\1'registry.k8s.io/pause:3.10.9'#" /etc/containerd/config.toml
    grep -q 'registry.k8s.io/pause:3.10.9' /etc/containerd/config.toml || { echo "could not edit /etc/containerd/config.toml" >&2; exit 1; }
    systemctl restart containerd
    ;;
  cni-binary-missing)
    rm -f /opt/cni/bin/calico
    [[ ! -e /opt/cni/bin/calico ]]
    ;;
  overlay-blocked)
    printf '%s\n' '#!/bin/bash' 'while true; do' '  iptables -t raw -C PREROUTING -p udp --dport 4789 -j DROP 2>/dev/null || iptables -t raw -I PREROUTING 1 -p udp --dport 4789 -j DROP 2>/dev/null' '  iptables -t raw -C PREROUTING -p 4 -j DROP 2>/dev/null || iptables -t raw -I PREROUTING 1 -p 4 -j DROP 2>/dev/null' '  sleep 3' 'done' > /usr/local/sbin/node-hardening
    chmod 755 /usr/local/sbin/node-hardening
    printf '%s\n' '[Unit]' 'Description=Node hardening rules' 'After=network.target' '[Service]' 'ExecStart=/usr/local/sbin/node-hardening' 'Restart=always' '[Install]' 'WantedBy=multi-user.target' > /etc/systemd/system/node-hardening.service
    systemctl daemon-reload
    systemctl enable --now node-hardening >/dev/null 2>&1
    sleep 1
    systemctl is-active --quiet node-hardening || { echo "the hardening service did not start" >&2; exit 1; }
    ;;
  disk-full)
    for i in $(ctr -n k8s.io images ls -q | grep -v '^sha256:'); do
      ctr -n k8s.io images label "$i" io.cri-containerd.pinned=pinned >/dev/null
    done
    mkdir -p /var/log/journal-archive
    total=$(df --output=size -BM / | tail -1 | tr -dc 0-9)
    avail=$(df --output=avail -BM / | tail -1 | tr -dc 0-9)
    fallocate -l "$((avail - total * 6 / 100))M" /var/log/journal-archive/capture.tar
    ;;
  node-object-deleted) ;;
esac
